{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Nevertheless, Cochrane Reviews have been greatly under-utilised in guidelines and recommendations are often based on lower-level evidence or expert consensus because of limitations regarding familiarity, awareness, usefulness, access, and time [12-21].",
      "reason": "The Introduction describes the current state of knowledge (role of systematic reviews, NMA vs PW-MA, NMA as highest level of evidence) and key uncertainties (under-utilisation of Cochrane reviews in guidelines, validity concerns of NMA assumptions)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "We anticipate that our research will highlight the extent of potential research waste, help review authors to maximise the impact of their reviews, aid guidelines developers to improve and increase the use of NMA and PW-MA reviews, and lead to improved collaboration to increase research efficiency.",
      "reason": "The importance and need for the review are explicitly explained, including anticipated benefits and the gap that no prior research has compared NMA and PW-MA review citation in guidelines."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Previous work has reviewed guidelines and summarised the type of evidence that underpinned recommendations [12, 13, 15]. Limited research has explored the use of NMAs to inform guidelines [38]. Lunny et al summarised how often NMAs and PW-MAs support recommendations in a sample of 50 guidelines [15]. Our article is the first to systematically search for reviews and summarise their citation in guidelines...",
      "reason": "Similar prior reviews are identified and cited (Lunny et al, Korfitsen et al), and the need for the current review is explained by building on and extending prior research."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a methodological/evidence-uptake review of Cochrane reviews' citation in guidelines, not a review of intervention effects of a clinical intervention; no mechanism of action is required or reported."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not evaluate a complex intervention or delivery context; it examines citation of reviews in guidelines, so a logic model is not applicable."
    }
  ],
  "confidence": 92
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "we build on prior research by conducting a systematic review of Cochrane Reviews that applied NMA to summarise which reviews were cited in guidelines in terms of review characteristics, when the reviews were cited, where the reviews were cited regarding location, who cited the reviews, and why the reviews were cited in terms of how the review contributed to the guideline.",
      "reason": "The Introduction explicitly states the review objectives (which, when, where, who, and why NMA reviews were cited in guidelines, plus a post hoc comparison with PW-MA reviews). The abstract (text_2) restates the aim: 'We aimed to summarise which, when, where, who, and why Cochrane Reviews that applied NMA were cited in guidelines; and to compare the citation of NMA reviews in guidelines with PW-MA reviews.'"
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_6",
      "quote": "conducting a systematic review of Cochrane Reviews that applied NMA to summarise which reviews were cited in guidelines",
      "reason": "This is a review of the citation/impact of reviews in guidelines, not a review of intervention effects; no planned treatment comparisons are being synthesized, so PICO-style comparison specification does not apply."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_8",
      "quote": "Cochrane Reviews of interventions that applied NMA were included. We excluded protocols, withdrawn reviews, overview of reviews, and diagnostic test accuracy reviews.",
      "reason": "Eligible review types are specified (Cochrane intervention reviews applying NMA), but this is a review-of-reviews; no study design, setting, or follow-up criteria for primary studies are specified, which is largely inherent to the design but not all question-framework components are explicit."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_8",
      "quote": "We excluded protocols, withdrawn reviews, overview of reviews, and diagnostic test accuracy reviews.",
      "reason": "Publication status is addressed (protocols and withdrawn reviews excluded), but no language restrictions or dissemination year limits for eligibility are reported (the search date in text_9 is a search parameter, not an eligibility criterion)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_8",
      "quote": "We excluded reviews that applied NMA but for which the main summary of findings table was based on PW-MA or single trials",
      "reason": "This review of reviews does not exclude studies based on outcome measurement versus outcome reporting; the conditional requirement does not apply."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence describes groups used in syntheses or links them to review objectives; the review summarizes citation impacts rather than defining synthesis groups in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "We excluded reviews that used indirect comparison methods (e.g. calculating the difference between results obtained from pairwise meta-analyses) rather than NMA models because indirect comparisons are made in reviews without using searchable terminology. We excluded reviews that applied NMA but for which the main summary of findings table was based on PW-MA or single trials because we primarily aimed to explore the uptake of NMA results in clinical guidelines.",
      "reason": "Rationales are explicitly provided for the notable eligibility restrictions (excluding indirect-comparison reviews and reviews whose SoF was not NMA-based)."
    }
  ],
  "confidence": 82
}

